do $$
declare cols text;
begin
  select string_agg(format('%I', attname), ', ' order by attnum) into cols from pg_attribute
   where attrelid = 'public."network_posts"'::regclass and attnum > 0 and not attisdropped and attname <> all (array['id', 'kind', 'title', 'body', 'transaction_type', 'property_type_ids', 'location_ids', 'location_scope_ids', 'feature_ids', 'price_min_cents', 'price_max_cents', 'currency', 'beds_min', 'baths_min', 'area_min_m2', 'area_max_m2', 'expires_at', 'created_at']);
  execute format('grant update (%s) on table public."network_posts" to app_user', cols);
end $$;
grant select, insert, update, delete on table public."network_posts" to app_system;
create policy definer_read on public."network_posts" for select to app_owner using (true);

